CREATE TYPE public.app_role AS ENUM ('creator','brand','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', avatar_path text, account_status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'creator');
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.creator_profiles(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, specialization text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', skills jsonb NOT NULL DEFAULT '[]', ai_tools jsonb NOT NULL DEFAULT '[]', social_links jsonb NOT NULL DEFAULT '{}', profile_completion smallint NOT NULL DEFAULT 0, verification_status text NOT NULL DEFAULT 'self_reported', details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.creator_profiles TO authenticated; GRANT ALL ON public.creator_profiles TO service_role;
ALTER TABLE public.creator_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY creator_owner ON public.creator_profiles FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.brand_profiles(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, company_name text NOT NULL DEFAULT '', representative_name text NOT NULL DEFAULT '', business_email text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', industry text NOT NULL DEFAULT '', company_size text NOT NULL DEFAULT '', turnover_range text NOT NULL DEFAULT '', business_address text NOT NULL DEFAULT '', gstin_protected text NOT NULL DEFAULT '', gst_format_status text NOT NULL DEFAULT 'not_checked', gst_verification_status text NOT NULL DEFAULT 'unavailable', approval_status text NOT NULL DEFAULT 'pending_admin_review', reviewed_by uuid REFERENCES public.profiles(id), reviewed_at timestamptz, rejection_reason text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.brand_profiles TO authenticated; GRANT UPDATE(company_name,representative_name,business_email,website,industry,company_size,turnover_range,business_address,gstin_protected,details) ON public.brand_profiles TO authenticated; GRANT ALL ON public.brand_profiles TO service_role;
ALTER TABLE public.brand_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY brand_read ON public.brand_profiles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY brand_insert ON public.brand_profiles FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND approval_status='pending_admin_review' AND gst_verification_status='unavailable');
CREATE POLICY brand_update ON public.brand_profiles FOR UPDATE TO authenticated USING(user_id=auth.uid() AND approval_status IN ('pending_admin_review','resubmission_required')) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.active_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),session_hash text,created_at timestamptz DEFAULT now(),last_activity timestamptz DEFAULT now(),revoked_at timestamptz,revocation_reason text,ip_hash text,user_agent_hash text);
GRANT ALL ON public.active_sessions TO service_role; ALTER TABLE public.active_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.portfolio_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id) NOT NULL,storage_path text NOT NULL,media_type text NOT NULL,title text NOT NULL,created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.portfolio_items TO authenticated; GRANT ALL ON public.portfolio_items TO service_role; ALTER TABLE public.portfolio_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY portfolio_owner ON public.portfolio_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.brand_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),storage_path text NOT NULL,document_type text NOT NULL,created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.brand_documents TO authenticated; GRANT ALL ON public.brand_documents TO service_role; ALTER TABLE public.brand_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_owner ON public.brand_documents FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.verification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),event_type text NOT NULL,status text NOT NULL,provider_reference text,reason text,created_at timestamptz DEFAULT now());
GRANT SELECT ON public.verification_events TO authenticated; GRANT ALL ON public.verification_events TO service_role; ALTER TABLE public.verification_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY verification_read ON public.verification_events FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_user_id uuid REFERENCES public.profiles(id),subject_user_id uuid REFERENCES public.profiles(id),action text NOT NULL,reason text,created_at timestamptz DEFAULT now());
GRANT SELECT ON public.admin_audit_logs TO authenticated; GRANT ALL ON public.admin_audit_logs TO service_role; ALTER TABLE public.admin_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin ON public.admin_audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),title text NOT NULL,body text NOT NULL,read_at timestamptz,created_at timestamptz DEFAULT now());
GRANT SELECT,UPDATE(read_at) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_owner ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.security_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),event_type text NOT NULL,ip_hash text,metadata jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
GRANT ALL ON public.security_events TO service_role; ALTER TABLE public.security_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.project_briefs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),title text NOT NULL,data jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'Draft',created_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.project_briefs TO authenticated; GRANT ALL ON public.project_briefs TO service_role; ALTER TABLE public.project_briefs ENABLE ROW LEVEL SECURITY;
CREATE POLICY briefs_owner ON public.project_briefs FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.shortlists(user_id uuid NOT NULL REFERENCES public.profiles(id),creator_id text NOT NULL,PRIMARY KEY(user_id,creator_id));
GRANT SELECT,INSERT,DELETE ON public.shortlists TO authenticated; GRANT ALL ON public.shortlists TO service_role; ALTER TABLE public.shortlists ENABLE ROW LEVEL SECURITY;
CREATE POLICY shortlist_owner ON public.shortlists FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.legacy_identities(original_user_id text PRIMARY KEY,email text NOT NULL UNIQUE,auth_user_id uuid UNIQUE,profile_data jsonb DEFAULT '{}');
GRANT ALL ON public.legacy_identities TO service_role; ALTER TABLE public.legacy_identities ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.initialize_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name) VALUES(NEW.id,coalesce(NEW.email,''),coalesce(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'creator'); RETURN NEW; END; $$;
CREATE TRIGGER initialize_qolabrate_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_account();